import java.util.*;
public class JobSequencing {
    public int[] scheduleJobs(int[] profit, int[] deadline) {
        int n = profit.length, maxD = Arrays.stream(deadline).max().getAsInt();
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        Arrays.sort(idx, (a,b) -> profit[b]-profit[a]);
        int[] slot = new int[maxD+1]; Arrays.fill(slot, -1);
        int totalProfit = 0, count = 0;
        for (int i : idx) {
            for (int j = deadline[i]; j >= 1; j--) {
                if (slot[j] == -1) { slot[j] = i; totalProfit += profit[i]; count++; break; }
            }
        }
        return new int[]{count, totalProfit};
    }
}

